//! Update safety for a real provider <- consumer <- Child dependency chain.
//! Uses histories generated by the production cleanup dispatcher. Parentage
//! alone grants no dependency: the two committed bindings are explicit.
#[cfg(verus_keep_ghost)]
use super::{
    authorizes, binding_at, execution, failed_prefix_retains_dependencies, released,
    CleanupCommand, CleanupReply,
};
#[cfg(verus_keep_ghost)]
use crate::{lifecycle_state::LifecycleState, Binding};
use vstd::prelude::*;
verus! {
/// Until the failed Child obtains a new accepted authorization, both its
/// consumer-provider and that consumer's provider retain their commitments.
/// Arbitrary finite retries and rejected commands are included. This states
/// safety, not that a callback will eventually return or succeed.
pub proof fn failed_child_keeps_chain(states:Seq<LifecycleState>,commands:Seq<CleanupCommand>,replies:Seq<CleanupReply>,
    child:usize,generation:u64,to_consumer:Binding,to_provider:Binding)
    requires execution(states,commands,replies),
        states[0].protocol().failed(child,generation),
        states[0].control().binding_recorded(child,to_consumer),
        states[0].control().binding_recorded(to_consumer.provider,to_provider),
        forall|j:int,g:u64|0<=j<commands.len() ==> !authorizes(commands[j],replies[j],child,g),
    ensures
        forall|j:int|0<=j<commands.len() ==> released(commands[j],replies[j])!=Some(child)
            && released(commands[j],replies[j])!=Some(to_consumer.provider)
            && released(commands[j],replies[j])!=Some(to_provider.provider),
        forall|j:int|0<=j<states.len() ==>
            states[j].control().binding_recorded(child,to_consumer)
            && states[j].control().binding_recorded(to_consumer.provider,to_provider)
            && states[j].control().registered(to_consumer.provider) && states[j].control().registered(to_provider.provider)
            && !states[j].control().is_restoring(to_consumer.provider) && !states[j].control().is_restoring(to_provider.provider)
            && !states[j].control().cleanup_enabled(to_consumer.provider) && !states[j].control().cleanup_enabled(to_provider.provider),
{
    failed_prefix_retains_dependencies(states,commands,replies,child,generation,to_consumer);
    assert forall|j:int|0<=j<commands.len() implies released(commands[j],replies[j])!=Some(to_consumer.provider) by {
        binding_at(states,commands,replies,child,to_consumer,j);
        assert(states[j+1].cleanup_step(&states[j],commands[j],replies[j]));
    }
    assert forall|j:int|0<=j<states.len() implies
        states[j].control().binding_recorded(child,to_consumer)
        && states[j].control().binding_recorded(to_consumer.provider,to_provider)
        && states[j].control().registered(to_consumer.provider) && states[j].control().registered(to_provider.provider)
        && !states[j].control().is_restoring(to_consumer.provider) && !states[j].control().is_restoring(to_provider.provider)
        && !states[j].control().cleanup_enabled(to_consumer.provider) && !states[j].control().cleanup_enabled(to_provider.provider) by {
        binding_at(states,commands,replies,child,to_consumer,j);
        binding_at(states,commands,replies,to_consumer.provider,to_provider,j);
    }
    assert forall|j:int|0<=j<commands.len() implies released(commands[j],replies[j])!=Some(to_provider.provider) by {
        assert(states[j+1].cleanup_step(&states[j],commands[j],replies[j]));
    }
}
}
